entry-admission.source:
program native_phase
use vm.core.convert
use std.compiler.nox.job
use std.compiler.nox.syntax
use std.compiler.nox.emit
use std.compiler.nox.module_graph
#[pure]
fn main(input:Noun)->Noun {
    let request=job.read(input)
    if (request.error.code == as_u32(0)) == false { return emit.failure(input,request.index,request.error) }

    // Intentional marker: reaching code 6 means this prefix completed.
    emit.failure(input,request.index,syntax.error(6,as_u32(0),as_u32(0)))
}

module-discovery.source:
program native_phase
use vm.core.convert
use std.compiler.nox.job
use std.compiler.nox.syntax
use std.compiler.nox.emit
use std.compiler.nox.module_graph
#[pure]
fn main(input:Noun)->Noun {
    let request=job.read(input)
    if (request.error.code == as_u32(0)) == false { return emit.failure(input,request.index,request.error) }
    let graph = module_graph.discover(request)
    if (graph.error.code == as_u32(0)) == false { return emit.failure(input, graph.error_index, graph.error) }
    // Intentional marker: reaching code 6 means this prefix completed.
    emit.failure(input,request.index,syntax.error(6,as_u32(0),as_u32(0)))
}

