use nox::{artifact, sequential, NoTrace, Outcome, Reduction};
use std::path::Path;
const LIMITS: artifact::Limits = artifact::Limits { max_bytes: 16 * 1024 * 1024, max_nodes: 196608, max_depth: 4096 };

fn main() {
    let args: Vec<_> = std::env::args().collect();
    let budget: u64 = args[3].parse().unwrap();
    let nodes: u32 = args[4].parse().unwrap();
    let mut arena = Reduction::<{ 1 << 24 }>::try_new_boxed().unwrap();
    assert!(arena.limit_allocations(nodes));
    let compiler = artifact::decode(&mut arena, &std::fs::read(&args[1]).unwrap(), LIMITS).unwrap();
    let job = artifact::decode(&mut arena, &std::fs::read(&args[2]).unwrap(), LIMITS).unwrap();
    let mut cursor = arena.tail(compiler).unwrap();
    for _ in 0..3 { cursor = arena.tail(cursor).unwrap(); }
    let formula = arena.head(cursor).unwrap();
    let loaded = arena.count();
    let start = std::time::Instant::now();
    let execution = sequential::reduce(&mut arena, job, formula, budget,
        sequential::Limits { max_frames: 65536 }, &mut NoTrace).unwrap();
    let (status, remaining, result) = match execution.outcome {
        Outcome::Ok(result, left) => ("returned", Some(left), Some(result)),
        Outcome::Halt(left) => ("budget_exhausted", Some(left), None),
        Outcome::Error(_) => ("execution_error", None, None),
    };
    if let Some(result) = result {
        let bytes = artifact::encode(&arena, result, LIMITS).unwrap();
        std::fs::write(Path::new(&args[5]).with_extension("dag"), bytes).unwrap();
    }
    let report = serde_json::json!({
        "scope": "Direct nox component diagnostic; independent of Joy admission. Extra runtime limits do not certify the original JOB request or self-hosting milestone.",
        "compiler": args[1], "job": args[2], "requested_budget": budget,
        "logical_nodes": nodes, "physical_nodes": 1u32 << 24,
        "loaded_nodes": loaded, "allocated_nodes": arena.count(),
        "remaining_budget": remaining, "charged_reductions": remaining.map(|r|budget-r),
        "peak_frames": execution.peak_frames, "outcome": format!("{:?}", execution.outcome),
        "status": status, "elapsed_ms": start.elapsed().as_millis(),
    });
    std::fs::write(&args[5], serde_json::to_string_pretty(&report).unwrap()+"\n").unwrap();
    println!("{}", report);
}

