use std::path::Path;
fn main() {
    let args: Vec<_> = std::env::args().collect();
    let repo = Path::new(&args[1]);
    let source = std::fs::read_to_string(&args[2]).unwrap();
    let mut options = trident::CompileOptions::default();
    options.module_sources.insert("std.compiler.nox.job".into(), source);
    for pair in args[4..].chunks_exact(2) {
        options.module_sources.insert(pair[0].clone(), std::fs::read_to_string(&pair[1]).unwrap());
    }
    let artifact = trident::compile_native_artifact_project(
        &repo.join("compiler/nox/main.tri"), &options,
        trident::NativeArtifactProfile::CompilerJob, trident::NATIVE_ARTIFACT_LIMITS,
    ).unwrap_or_else(|errors| panic!("{errors:?}"));
    std::fs::write(&args[3], artifact.bytes).unwrap();
}

